from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/header_test")
async def header_test(x_header: str = Header(None, convert_underscores=True)):
    return {"x_header": x_header}

@app.get("/header_test_no_convert")
async def header_test_no_convert(x_header: str = Header(None, convert_underscores=False)):
    return {"x_header": x_header}

client = TestClient(app)

def test_convert_underscores_true_rejects_underscore():
    # When convert_underscores=True (default), it should NOT accept 'X_Header'
    # It should only accept 'X-Header'
    response = client.get("/header_test", headers={"X_Header": "underscore"})
    assert response.json() == {"x_header": None}

    response = client.get("/header_test", headers={"X-Header": "hyphen"})
    assert response.json() == {"x_header": "hyphen"}

def test_convert_underscores_false_accepts_underscore():
    # When convert_underscores=False, it SHOULD accept 'X_Header'
    response = client.get("/header_test_no_convert", headers={"X_Header": "underscore"})
    assert response.json() == {"x_header": "underscore"}

if __name__ == "__main__":
    import pytest
    pytest.main([__file__])

